from pathlib import Path

BACKEND = Path("backend/main.py")
INDEX = Path("index.html")


def patch_backend():
    source = BACKEND.read_text(encoding="utf-8")

    if "AI_EXPERT_IMPORT_V1" not in source:
        anchor = "app = FastAPI()"
        block = '''# AI_EXPERT_IMPORT_V1\ntry:\n    from backend.ai_expert import build_ai_expert_analysis\nexcept ImportError:\n    from ai_expert import build_ai_expert_analysis\n\n'''
        if anchor not in source:
            raise SystemExit("backend app anchor not found")
        source = source.replace(anchor, block + anchor, 1)

    if "AI_EXPERT_BACKEND_V1" not in source:
        anchor = '''        ai_reconstruction = augment_ai_reconstruction_with_prearm_diagnostics(\n            ai_reconstruction, timeline\n        )\n'''
        block = '''\n        # AI_EXPERT_BACKEND_V1\n        ai_expert = None\n        ai_expert_warning = None\n        try:\n            _expert_radio_events = []\n            for _ep in communication_loss_episodes:\n                _start = _ep.get("startTimestamp")\n                if not valid_number(_start):\n                    continue\n                _expert_radio_events.append({\n                    "time_s": float(_start) - float(base_t),\n                    "dbm": _ep.get("startDbm"),\n                    "recovered": bool(_ep.get("recovered")),\n                    "vtx_changed": bool(_ep.get("vtxChangedAcrossBlindZone")),\n                })\n\n            # RADIO/GCS failsafe is a separate evidence class from a raw MAVLink gap.\n            for _row in timeline:\n                if not isinstance(_row, dict):\n                    continue\n                _text = str(_row.get("systemText") or _row.get("system_text") or "").strip()\n                _lower = _text.lower()\n                if "failsafe" not in _lower or not ("radio" in _lower or "gcs" in _lower):\n                    continue\n                _t_ms = _timeline_graph_time_ms(_row.get("time"))\n                if _t_ms is None:\n                    continue\n                _expert_radio_events.append({\n                    "time_s": float(_t_ms) / 1000.0,\n                    "type": "failsafe",\n                    "text": _text,\n                })\n\n            _expert_thrust_events = []\n            for _event in potential_thrust_loss_events:\n                _ts = _event.get("timestamp")\n                if not valid_number(_ts):\n                    continue\n                _expert_thrust_events.append({\n                    "time_s": float(_ts) - float(base_t),\n                    "text": _event.get("text") or "Potential Thrust Loss",\n                    "motors": _event.get("motors"),\n                    "mode": _event.get("mode"),\n                })\n\n            _expert_rpm_events = []\n            for _event in rpm_drop_events:\n                _ts = _event.get("timestamp")\n                if not valid_number(_ts):\n                    continue\n                _expert_rpm_events.append({\n                    "time_s": float(_ts) - float(base_t),\n                    "differencePct": _event.get("differencePct"),\n                    "lowerMotor": _event.get("lowerMotor"),\n                    "higherMotor": _event.get("higherMotor"),\n                    "type": "rpm_drop",\n                    "drop": True,\n                })\n\n            ai_expert = build_ai_expert_analysis(\n                timeline=timeline,\n                radio_events=_expert_radio_events,\n                thrust_events=_expert_thrust_events,\n                rpm_events=_expert_rpm_events,\n            )\n        except Exception as exc:\n            ai_expert_warning = f"Поглиблений аналіз недоступний: {exc}"\n'''
        if anchor not in source:
            raise SystemExit("AI reconstruction augmentation anchor not found")
        source = source.replace(anchor, anchor + block, 1)

    if '"ai_expert": ai_expert,' not in source:
        anchor = '            "ai_reconstruction": ai_reconstruction,\n'
        replacement = (
            anchor
            + '            "ai_expert": ai_expert,\n'
            + '            "ai_expert_warning": ai_expert_warning,\n'
        )
        if anchor not in source:
            raise SystemExit("AI reconstruction response anchor not found")
        source = source.replace(anchor, replacement, 1)

    BACKEND.write_text(source, encoding="utf-8")


def patch_frontend():
    source = INDEX.read_text(encoding="utf-8")

    if "AI_EXPERT_V1" not in source:
        anchor = '''    <!-- AI_RECONSTRUCTION_V1 -->\n    <section id="aiReconstructionBlock" class="ai-reconstruction" hidden>\n      <h3>ТЕХНІЧНИЙ ВИСНОВОК</h3>\n      <div id="aiReconWhat"></div>\n      <div id="aiReconSequence"></div>\n      <div id="aiReconActions"></div>\n      <div id="aiReconAlternatives"></div>\n      <div id="aiReconConfidence"></div>\n    </section>\n'''
        block = '''\n    <!-- AI_EXPERT_V1 -->\n    <section id="aiExpertBlock" class="ai-expert" hidden>\n      <h3>ПОГЛИБЛЕНИЙ АНАЛІЗ ПОЛЬОТУ</h3>\n      <div id="aiExpertSummary"></div>\n      <div id="aiExpertSessions" class="ai-expert-sessions"></div>\n      <div id="aiExpertDetails"></div>\n    </section>\n'''
        if anchor not in source:
            raise SystemExit("AI reconstruction frontend anchor not found")
        source = source.replace(anchor, anchor + block, 1)

    if "AI_EXPERT_STYLE_V1" not in source:
        css = '''\n<style>\n/* AI_EXPERT_STYLE_V1 */\n.ai-expert{background:var(--bg-card);border:1px solid var(--border-color);border-left:4px solid var(--accent);border-radius:8px;padding:20px 22px;margin:-14px 0 30px}\n.ai-expert[hidden]{display:none!important}\n.ai-expert h3{margin:0 0 12px;font-size:19px}\n.ai-expert-summary{margin:0 0 14px;font-weight:700;line-height:1.55}\n.ai-expert-sessions{display:grid;gap:10px}\n.ai-expert-session{border:1px solid var(--border-color);border-radius:8px;background:var(--bg-header);overflow:hidden}\n.ai-expert-session>summary{cursor:pointer;list-style:none;padding:12px 14px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-weight:800}\n.ai-expert-session>summary::-webkit-details-marker{display:none}\n.ai-expert-session>summary:before{content:'▶';font-size:10px;color:var(--text-muted);transition:transform .15s}\n.ai-expert-session[open]>summary:before{transform:rotate(90deg)}\n.ai-expert-session.severity-critical{border-left:4px solid var(--danger)}\n.ai-expert-session.severity-warning{border-left:4px solid var(--warning)}\n.ai-expert-session.severity-info{border-left:4px solid var(--success)}\n.ai-expert-session-badge{font-size:10px;letter-spacing:.35px;text-transform:uppercase;color:var(--text-muted);border:1px solid var(--border-highlight);border-radius:999px;padding:2px 7px}\n.ai-expert-session-meta{color:var(--text-muted);font-size:12px;font-weight:600;margin-left:auto}\n.ai-expert-body{padding:0 14px 15px;border-top:1px solid var(--border-color)}\n.ai-expert-conclusion{margin:12px 0;font-weight:700;line-height:1.5;white-space:pre-wrap}\n.ai-expert-section{margin-top:15px}\n.ai-expert-section h4{margin:0 0 6px;color:var(--text-muted);font-size:11px;letter-spacing:.45px;text-transform:uppercase}\n.ai-expert-section ul{margin:0;padding-left:20px;line-height:1.5}\n.ai-expert-section li{margin:3px 0}\n.ai-expert-chronology{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}\n.ai-expert-subsystems{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:8px;margin-top:12px}\n.ai-expert-subsystem{border:1px solid var(--border-color);border-radius:7px;padding:10px;background:var(--bg-card)}\n.ai-expert-subsystem-title{font-weight:800;margin-bottom:4px}\n.ai-expert-subsystem-meta{color:var(--text-muted);font-size:11px;margin-bottom:5px}\n.ai-expert-subsystem ul{margin:0;padding-left:18px;font-size:12px;line-height:1.45}\n.ai-expert-warning{margin-top:12px;color:var(--warning);font-size:12px}\n@media(max-width:760px){.ai-expert-session-meta{width:100%;margin-left:20px}.ai-expert{padding:16px 14px}}\n</style>\n'''
        if "</head>" not in source:
            raise SystemExit("frontend head anchor not found")
        source = source.replace("</head>", css + "\n</head>", 1)

    if "function renderAiExpert(expert)" not in source:
        anchor = "function renderResults(data){"
        renderer = '''function formatExpertTime(sec){\n  const value=Number(sec);\n  if(!Number.isFinite(value))return '—';\n  const total=Math.max(0,value);\n  const minutes=Math.floor(total/60);\n  const seconds=total-minutes*60;\n  return `${String(minutes).padStart(2,'0')}:${seconds.toFixed(1).padStart(4,'0')}`;\n}\n\nfunction expertStatusText(status){\n  return ({confirmed_problem:'ПРОБЛЕМА ПІДТВЕРДЖЕНА',probable_problem:'ЙМОВІРНА ПРОБЛЕМА',no_significant_issue:'ЗНАЧНИХ ВІДХИЛЕНЬ НЕ ВИЯВЛЕНО',unknown:'НЕВІДОМО'})[status]||String(status||'НЕВІДОМО');\n}\n\nfunction expertSeverityText(severity){\n  return ({critical:'Критична',warning:'Потребує уваги',info:'Норма/інформація'})[severity]||String(severity||'');\n}\n\nfunction appendExpertList(host,title,items,extraClass=''){\n  if(!host||!Array.isArray(items)||!items.length)return;\n  const section=document.createElement('section');\n  section.className=`ai-expert-section ${extraClass}`.trim();\n  const heading=document.createElement('h4');heading.textContent=title;\n  const list=document.createElement('ul');\n  items.forEach(item=>{const li=document.createElement('li');li.textContent=String(item);list.appendChild(li);});\n  section.append(heading,list);host.appendChild(section);\n}\n\nfunction renderAiExpert(expert){\n  const block=document.getElementById('aiExpertBlock');\n  const summaryHost=document.getElementById('aiExpertSummary');\n  const sessionsHost=document.getElementById('aiExpertSessions');\n  const detailsHost=document.getElementById('aiExpertDetails');\n  if(!block||!summaryHost||!sessionsHost||!detailsHost)return;\n  summaryHost.replaceChildren();sessionsHost.replaceChildren();detailsHost.replaceChildren();\n  if(!expert||!Array.isArray(expert.sessions)||!expert.sessions.length){block.hidden=true;return;}\n\n  const summary=document.createElement('p');\n  summary.className='ai-expert-summary';\n  summary.textContent=String(expert.summary||'');\n  summaryHost.appendChild(summary);\n\n  const subsystemLabels={radio:'Зв’язок / MAVLink',navigation:'Навігація / GPS / EKF',power:'Живлення / батарея',propulsion:'ESC / RPM / тяга',control:'Керування / режими',termination:'Завершення польоту'};\n  expert.sessions.forEach(session=>{\n    const details=document.createElement('details');\n    details.className=`ai-expert-session severity-${session.overall_severity||'info'}`;\n    details.open=Number(session.session_id)===Number(expert.primary_session_id);\n\n    const head=document.createElement('summary');\n    const title=document.createElement('span');\n    title.textContent=session.classification==='flight'?`Політ №${session.session_id}`:`ARM-сесія №${session.session_id}`;\n    const badge=document.createElement('span');\n    badge.className='ai-expert-session-badge';\n    badge.textContent=session.classification==='flight'?'ПОЛІТ':session.classification==='arm_check'?'КОРОТКА ARM-ПЕРЕВІРКА':'НЕВИЗНАЧЕНА';\n    const meta=document.createElement('span');\n    meta.className='ai-expert-session-meta';\n    const endState=session.ended_with_disarm?`DISARM ${formatExpertTime(session.end_s)}`:session.ended_by_log?'DISARM не зафіксовано':'завершення невідоме';\n    meta.textContent=`ARM ${formatExpertTime(session.start_s)} • ${endState} • ${formatExpertTime(session.duration_s)} • ${expertSeverityText(session.overall_severity)}`;\n    head.append(title,badge,meta);\n    details.appendChild(head);\n\n    const body=document.createElement('div');body.className='ai-expert-body';\n    const conclusion=document.createElement('p');conclusion.className='ai-expert-conclusion';conclusion.textContent=String(session.short_conclusion||'');body.appendChild(conclusion);\n\n    const chronology=(session.chronology||[]).map(event=>`${formatExpertTime(event.time_s)} — ${event.text||event.type||'подія'}`);\n    appendExpertList(body,'ХРОНОЛОГІЯ КЛЮЧОВИХ ПОДІЙ',chronology,'ai-expert-chronology');\n\n    const subsystemGrid=document.createElement('div');subsystemGrid.className='ai-expert-subsystems';\n    Object.entries(session.subsystems||{}).forEach(([key,module])=>{\n      const card=document.createElement('article');card.className='ai-expert-subsystem';\n      const cardTitle=document.createElement('div');cardTitle.className='ai-expert-subsystem-title';cardTitle.textContent=subsystemLabels[key]||key;\n      const cardMeta=document.createElement('div');cardMeta.className='ai-expert-subsystem-meta';\n      const confidence=Math.round(Number(module?.confidence||0)*100);\n      cardMeta.textContent=`${expertStatusText(module?.status)} • підтримка даними ${confidence}%`;\n      card.append(cardTitle,cardMeta);\n      if(Array.isArray(module?.evidence)&&module.evidence.length){const ul=document.createElement('ul');module.evidence.forEach(text=>{const li=document.createElement('li');li.textContent=String(text);ul.appendChild(li);});card.appendChild(ul);}\n      subsystemGrid.appendChild(card);\n    });\n    if(subsystemGrid.childElementCount)body.appendChild(subsystemGrid);\n\n    appendExpertList(body,'ПІДТВЕРДЖЕНО TLOG',session.confirmed);\n    appendExpertList(body,'ЙМОВІРНА ІНТЕРПРЕТАЦІЯ',session.interpretation);\n    appendExpertList(body,'ЩО НЕМОЖЛИВО ВСТАНОВИТИ',session.unknowns);\n    appendExpertList(body,'ЩО ПЕРЕВІРИТИ',session.checks);\n    details.appendChild(body);\n    sessionsHost.appendChild(details);\n  });\n\n  if(Array.isArray(expert.warnings)&&expert.warnings.length){\n    const warning=document.createElement('div');warning.className='ai-expert-warning';warning.textContent=expert.warnings.join(' • ');detailsHost.appendChild(warning);\n  }\n  block.hidden=false;\n}\n\n'''
        if anchor not in source:
            raise SystemExit("frontend renderResults anchor not found")
        source = source.replace(anchor, renderer + anchor, 1)

    if "renderAiExpert(data.ai_expert)" not in source:
        anchor = "  renderAiReconstruction(data.ai_reconstruction);"
        replacement = '''  if(data.ai_expert&&Array.isArray(data.ai_expert.sessions)&&data.ai_expert.sessions.length){\n    renderAiExpert(data.ai_expert);\n    const legacyRecon=document.getElementById('aiReconstructionBlock');\n    if(legacyRecon)legacyRecon.hidden=true;\n  }else{\n    renderAiExpert(null);\n    renderAiReconstruction(data.ai_reconstruction);\n  }'''
        if anchor not in source:
            raise SystemExit("frontend AI reconstruction render anchor not found")
        source = source.replace(anchor, replacement, 1)

    INDEX.write_text(source, encoding="utf-8")


patch_backend()
patch_frontend()
print("Applied AI flight expert backend + frontend integration")
